//! MLIL operations as Binary Ninja 6.1 numbers them, with the layout of their raw
//! operands.  Generated from the Python API's tables; do not edit by hand.

/// The kind of one raw operand slot.  `Expr`, `Int`, `Var`, `Float` and `Intrinsic` occupy one of the
/// five slots of a core instruction; the others occupy two (a count or state, then a list index or value).
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub enum OperandKind {
    Expr,
    Int,
    Var,
    Float,
    Intrinsic,
    ExprList,
    VarList,
    IntList,
    VarSsa,
    VarSsaDestAndSrc,
    VarSsaList,
    TargetMap,
    ConstantData,
    Constraint,
}

impl OperandKind {
    /// How many of the five raw slots this operand takes.
    pub fn slots(self) -> usize {
        match self {
            OperandKind::Expr | OperandKind::Int | OperandKind::Var | OperandKind::Float
            | OperandKind::Intrinsic | OperandKind::Constraint => 1,
            _ => 2,
        }
    }
}

