impl Op {
    pub const COUNT: usize = OP_COUNT;

    /// The operation with the core's enum value `value`.
    pub fn from_u32(value: u32) -> Option<Op> {
        if (value as usize) < OP_COUNT {
            // SAFETY: every value below OP_COUNT is a declared discriminant.
            Some(unsafe { std::mem::transmute::<u16, Op>(value as u16) })
        } else {
            None
        }
    }

    /// The core's name, `MLIL_SET_VAR`.
    pub fn name(self) -> &'static str {
        NAMES[self as usize]
    }

    /// The name without its prefix, `SET_VAR`.
    pub fn short_name(self) -> &'static str {
        &NAMES[self as usize][5..]
    }

    /// The operation named `name`, with or without the `MLIL_` prefix.
    pub fn from_name(name: &str) -> Option<Op> {
        let full = name.strip_prefix("MLIL_").unwrap_or(name);
        NAMES.iter().position(|n| &n[5..] == full).and_then(|i| Op::from_u32(i as u32))
    }

    /// The kinds of the operation's operands, in slot order.
    pub fn layout(self) -> &'static [OperandKind] {
        LAYOUT[self as usize]
    }
}

